'use client';
import React from 'react';

import * as Picker from 'emoji-picker-react/primitives';


// Custom markup for every emoji cell and section header. Components are
// defined at module scope: a new identity would remount every cell.
function Cell({ emoji: _emoji, className, ...props }: Picker.EmojiRenderProps) {
  return <button {...props} className={`${className} w95-cell`} />;
}

function Header({ category, className, ...props }: Picker.CategoryHeaderRenderProps) {
  return (
    <h3 {...props} className={`${className} w95-header`}>
      {category.name.toUpperCase()}
    </h3>
  );
}

const components = { Emoji: Cell, CategoryHeader: Header };

function StatusBar() {
  const emoji = Picker.useActiveEmoji();
  return (
    <div className="w95-status">
      {emoji ? `${emoji.emoji}  ${emoji.names[emoji.names.length - 1]}` : 'Ready'}
    </div>
  );
}

export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  return (
    <div className="w95-window">
      <div className="w95-title">
        <span>Emoji Picker.exe</span>
        <button type="button" aria-label="Close">
          ×
        </button>
      </div>
      <RootComponent appearance="default"         className={className}
      >
        <Picker.CategoryNav />
        <Picker.Viewport>
          <Picker.List components={components} />
        </Picker.Viewport>
        <StatusBar />
      </RootComponent>
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.w95-window {
  --w95-face: #c0c0c0;
  --w95-light: #ffffff;
  --w95-dark: #808080;
  --w95-darker: #000000;
  width: 380px;
  padding: 3px;
  background: var(--w95-face);
  box-shadow:
    inset -1px -1px var(--w95-darker),
    inset 1px 1px var(--w95-face),
    inset -2px -2px var(--w95-dark),
    inset 2px 2px var(--w95-light);
  font-family: 'MS Sans Serif', 'Microsoft Sans Serif', Tahoma, Geneva,
    sans-serif;
  font-size: 12px;
}
.w95-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 3px 3px 6px;
  background: linear-gradient(90deg, #000080, #1084d0);
  color: #fff;
  font-weight: 700;
}
.w95-title button {
  width: 16px;
  height: 14px;
  padding: 0;
  border: 0;
  background: var(--w95-face);
  box-shadow:
    inset -1px -1px var(--w95-darker),
    inset 1px 1px var(--w95-light),
    inset -2px -2px var(--w95-dark);
  font: 700 10px/1 sans-serif;
}

/* Windows 95 — a fully custom look: bevelled window chrome, custom emoji
   cells and section headers through List `components`, and a status bar
   driven by useActiveEmoji(). Every interaction is still the library's. */
/* Picker styles — the source of truth for every stack variant. */
.w95-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #000000;
  --epr-category-label-height: 22px;
  --epr-category-icon-active-color: #000000;
  --epr-category-icon-inactive-color: #404040;
  --epr-category-navigation-button-size: 22px;
  --epr-emoji-variation-picker-bg-color: var(--w95-face);
  --epr-emoji-size: 24px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 6px;
  height: 360px;
  margin-top: 3px;
  background: var(--w95-face);
}
.w95-picker [data-epr-part='category-nav'] > * {
  justify-content: flex-start;
  gap: 2px;
  padding: 4px 2px;
}
.w95-picker [data-epr-part='category-tab'] {
  width: 30px;
  height: 26px;
  padding: 2px 4px;
  border-radius: 0;
  background: var(--w95-face);
  box-shadow:
    inset -1px -1px var(--w95-darker),
    inset 1px 1px var(--w95-light),
    inset -2px -2px var(--w95-dark);
}
.w95-picker [data-epr-part='category-tab'][aria-selected='true'] {
  box-shadow:
    inset -1px -1px var(--w95-light),
    inset 1px 1px var(--w95-darker),
    inset 2px 2px var(--w95-dark);
}
.w95-picker [data-epr-part='viewport'] {
  margin: 0 2px;
  background: #fff;
  box-shadow:
    inset -1px -1px var(--w95-light),
    inset 1px 1px var(--w95-dark),
    inset 2px 2px var(--w95-darker);
}
.w95-picker .w95-header {
  margin: 0;
  padding: 0 6px;
  background: #000080;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.w95-picker .w95-cell {
  cursor: pointer;
  border: 0;
  background-color: transparent;
  outline: none;
  border-radius: 0;
}
.w95-picker .w95-cell:hover,
.w95-picker .w95-cell:focus {
  background: #000080;
}
.w95-picker .w95-status {
  display: flex;
  gap: 6px;
  align-items: center;
  height: 22px;
  margin-top: 3px;
  padding: 0 6px;
  box-shadow:
    inset -1px -1px var(--w95-light),
    inset 1px 1px var(--w95-dark);
}

